import { useMemo } from 'react';
import * as d3 from 'd3';

// ---- inlined from treeOfLife ----
/** A clade. `length` is the branch length from the parent: evolutionary distance, not depth. */
interface Clade {
  id: string;
  name?: string;
  length: number;
  branchset?: Clade[];
}

const DOMAINS = ['Bacteria', 'Archaea', 'Eukaryota'] as const;

function mulberry32(seed: number): () => number {
  let state = seed;
  return () => {
    state = (state + 0x6d2b79f5) | 0;
    let t = Math.imul(state ^ (state >>> 15), 1 | state);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const STEMS = [
  'Thermo', 'Halo', 'Methano', 'Pyro', 'Sulfo', 'Nitro', 'Aero', 'Bacillo',
  'Chloro', 'Cyano', 'Ferro', 'Litho', 'Myco', 'Oxalo', 'Photo', 'Rhodo',
  'Spiro', 'Strepto', 'Vibrio', 'Xantho', 'Acido', 'Baro', 'Crypto', 'Desulfo'
];

const TAILS = [
  'coccus', 'bacter', 'philus', 'spira', 'monas', 'vibrio', 'myces', 'phaga',
  'globus', 'nema', 'plasma', 'sarcina'
];

/**
 * Grows one deterministic phylogeny. Leaf branches draw from a squared distribution so
 * tip distances stay ragged, which is what makes the accumulated radius worth plotting.
 */
function build(): Clade {
  const random = mulberry32(20260813);
  const used = new Set<string>();
  let counter = 0;

  const pick = (list: readonly string[]) => list[Math.floor(random() * list.length)];

  const leafName = (): string => {
    const base = pick(STEMS) + pick(TAILS);
    let name = base;
    for (let suffix = 1; used.has(name); suffix++) name = `${base} ${String.fromCharCode(65 + suffix)}`;
    used.add(name);
    return name;
  };

  const grow = (depth: number): Clade => {
    const id = `n${counter++}`;
    if (depth === 0 || (depth < 3 && random() < 0.28)) {
      return { id, name: leafName(), length: 0.05 + random() ** 2 * 0.45 };
    }
    const children = 2 + Math.floor(random() * 2);
    return {
      id,
      length: 0.02 + random() * 0.12,
      branchset: Array.from({ length: children }, () => grow(depth - 1))
    };
  };

  return {
    id: 'life',
    name: 'Life',
    length: 0,
    branchset: DOMAINS.map((domain, i) => ({
      id: domain.toLowerCase(),
      name: domain,
      length: 0.04 + i * 0.02,
      branchset: grow(i === 0 ? 5 : 4).branchset
    }))
  };
}

const treeOfLife: Clade = build();

/** A clade; `length` is the branch length from its parent, evolutionary distance not depth. */
type CladeNode = { id: string; name?: string; length: number; branchset?: CladeNode[] };

/** The phylogeny root, plus the domain names that colour its depth-1 clades. */
export type Data = { tree: CladeNode; domains: readonly string[] };

const DEMO: Data = { tree: treeOfLife, domains: DOMAINS };

type Node = d3.HierarchyPointNode<CladeNode>;

const MAX_SIZE = 640;
/** Radial room outside the leaf ring for the longest taxon label. */
const LABEL_SPACE = 100;
const FONT_SIZE = 9;
const LABEL_GAP = 4;
const CAPTION = 'Synthetic phylogeny from a seeded generator, not a published tree of life.';

/** Distance from the root to the furthest tip, in branch-length units. */
function maxLength(d: d3.HierarchyNode<CladeNode>): number {
  return d.data.length + (d.children ? d3.max(d.children, maxLength) ?? 0 : 0);
}

/** A radial elbow: arc along the source radius to the target angle, then straight outward. */
function linkStep(a0: number, r0: number, a1: number, r1: number): string {
  const t0 = ((a0 - 90) / 180) * Math.PI;
  const t1 = ((a1 - 90) / 180) * Math.PI;
  const [c0, s0, c1, s1] = [Math.cos(t0), Math.sin(t0), Math.cos(t1), Math.sin(t1)];
  const arc = a0 === a1 ? '' : `A${r0},${r0} 0 0 ${a1 > a0 ? 1 : 0} ${r0 * c1},${r0 * s1}`;
  return `M${r0 * c0},${r0 * s0}${arc}L${r1 * c1},${r1 * s1}`;
}

export default function TreeOfLife({ data = DEMO, width }: { data?: Data; width: number }) {
  const height = Math.min(width, MAX_SIZE);
  const outerRadius = height / 2;
  const innerRadius = Math.max(outerRadius - LABEL_SPACE, 0);

  const color = useMemo(
    () => d3.scaleOrdinal<string, string>().domain(data.domains).range(d3.schemeObservable10),
    [data]
  );

  const { root, radiusOf, colorOf } = useMemo(() => {
    const tree = d3
      .hierarchy<CladeNode>(data.tree, (d) => d.branchset)
      .sum((d) => (d.branchset ? 0 : 1))
      .sort((a, b) => (a.value ?? 0) - (b.value ?? 0) || d3.ascending(a.data.length, b.data.length));

    // d3.cluster spans the full angle, so leaf 0 and leaf n-1 would collide at 12 o'clock.
    // Shrinking the span by one step spaces every leaf evenly around the circle instead.
    const leaves = tree.leaves().length;
    const laidOut = d3
      .cluster<CladeNode>()
      .size([(360 * (leaves - 1)) / leaves, innerRadius])
      .separation(() => 1)(tree);

    // The radius is accumulated branch length, not depth: this is what makes the tips ragged.
    const scale = innerRadius / maxLength(laidOut);
    const radiusOf = new Map<Node, number>();
    const setRadius = (d: Node, from: number) => {
      const to = from + d.data.length;
      radiusOf.set(d, to * scale);
      d.children?.forEach((child) => setRadius(child, to));
    };
    setRadius(laidOut, 0);

    const colorOf = new Map<Node, string>();
    const setColor = (d: Node, inherited: string) => {
      const own = d.depth === 1 ? color(d.data.name ?? '') : inherited;
      colorOf.set(d, own);
      d.children?.forEach((child) => setColor(child, own));
    };
    setColor(laidOut, 'var(--muted)');

    return { root: laidOut, radiusOf, colorOf };
  }, [data, innerRadius, color]);

  // Under one font size of arc between neighbouring tips the labels would overlap.
  const labelsFit = useMemo(() => {
    const angles = root.leaves().map((d) => d.x);
    const gap = d3.min(angles.slice(1).map((a, i) => a - angles[i])) ?? 0;
    return ((gap * Math.PI) / 180) * innerRadius >= FONT_SIZE;
  }, [root, innerRadius]);

  if (width === 0) return null;

  return (
    <svg
      viewBox={`${-width / 2} ${-height / 2} ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label={`Radial phylogenetic tree of ${root.leaves().length} taxa across three domains of life, where the distance of each tip from the centre is its accumulated branch length. ${CAPTION}`}
    >
      {/* Dotted extensions carry each tip out to the label ring so names stay aligned. */}
      <g fill="none" stroke="var(--line)" strokeDasharray="1,3">
        {root.leaves().map((d) => (
          <path key={d.data.id} d={linkStep(d.x, radiusOf.get(d) ?? 0, d.x, innerRadius)} />
        ))}
      </g>

      <g fill="none" strokeWidth={1.2}>
        {root.links().map((l) => (
          <path
            key={l.target.data.id}
            d={linkStep(
              l.source.x,
              radiusOf.get(l.source) ?? 0,
              l.target.x,
              radiusOf.get(l.target) ?? 0
            )}
            stroke={colorOf.get(l.target)}
            strokeOpacity={l.target.children ? 0.9 : 0.55}
          />
        ))}
      </g>

      {labelsFit && (
        <g fontSize={FONT_SIZE} fill="var(--text)">
          {root.leaves().map((d) => {
            const flipped = d.x >= 180;
            return (
              <text
                key={d.data.id}
                transform={`rotate(${d.x - 90}) translate(${innerRadius + LABEL_GAP},0)${flipped ? ' rotate(180)' : ''}`}
                textAnchor={flipped ? 'end' : 'start'}
                dy="0.31em"
              >
                {d.data.name}
              </text>
            );
          })}
        </g>
      )}

      <g fontSize={11} fill="var(--text)" transform={`translate(${-width / 2 + 8},${-height / 2 + 8})`}>
        {data.domains.map((domain, i) => (
          <g key={domain} transform={`translate(0,${i * 18})`}>
            <rect width={12} height={12} fill={color(domain)} />
            <text x={18} y={6} dy="0.35em">
              {domain}
            </text>
          </g>
        ))}
      </g>

      <text
        y={height / 2 - 6}
        textAnchor="middle"
        fontSize={10}
        fill="var(--muted)"
      >
        {CAPTION}
      </text>
    </svg>
  );
}
